async def convert_docx_to_pdf(
    client: HaxcmsClient,
    settings: Settings,
    source: str,
) -> dict[str, Any]:
    """Convert an uploaded DOCX file to a PDF document.

    NEEDS CHROME on the HAXcms server (puppeteer-core; PUPPETEER_EXECUTABLE_PATH or a
    system Chrome) - without it the conversion fails upstream.
    `source`: a path / URL / data: / base64: file (Sources convention), sent as the
    multipart file part (Word document (.docx) to convert to PDF).

    The binary result is written under the Output Directory; returns {path, bytes,
    mimetype, filename}.
    """
    resolved = await resolve_source(source, settings)
    files = {"file-upload": (resolved.filename, resolved.data, resolved.mimetype)}
    content = await system_api.action(client, "docxToPdf", files=files, raw=True)
    filename = Path(resolved.filename).stem + ".pdf"
    return conversion.write_bytes(
        content,
        mimetype="application/pdf",
        filename=filename,
        output_dir=settings.output_dir,
    )
